1	/**
2	 * Organization Module — single source of truth for departments, phases, and
3	 * the agent registry. Replaces the hardcoded AGENT_PIPELINE / AGENT_ROLES
4	 * constants previously in server.js.
5	 *
6	 * Data lives in ~/.claude/org/:
7	 *   - departments.json — department + phase definitions
8	 *   - registry.json    — per-agent record (department, phase, reportsTo,
9	 *                        experience, level, skills, status, hire date)
10	 *
11	 * This module is pure — it reads/writes JSON. Experience computation lives
12	 * in src/experience.js and reads from here.
13	 */
14	
15	const fs = require('fs');
16	const path = require('path');
17	const os = require('os');
18	
19	const HOME = os.homedir();
20	const ORG_DIR = path.join(HOME, '.claude', 'org');
21	const DEPARTMENTS_PATH = path.join(ORG_DIR, 'departments.json');
22	const REGISTRY_PATH = path.join(ORG_DIR, 'registry.json');
23	
24	function ensureDir(dir) {
25	  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
26	}
27	
28	function readJson(filePath, fallback) {
29	  try {
30	    if (!fs.existsSync(filePath)) return fallback;
31	    return JSON.parse(fs.readFileSync(filePath, 'utf-8'));
32	  } catch (err) {
33	    console.warn(`[org] failed to read ${filePath}: ${err.message}`);
34	    return fallback;
35	  }
36	}
37	
38	function writeJson(filePath, data) {
39	  ensureDir(path.dirname(filePath));
40	  // Atomic write: write to .tmp then rename
41	  const tmp = filePath + '.tmp';
42	  fs.writeFileSync(tmp, JSON.stringify(data, null, 2));
43	  fs.renameSync(tmp, filePath);
44	}
45	
46	// ──────────────────────────────────────────────────────────────────────────
47	//  Departments & Phases
48	// ──────────────────────────────────────────────────────────────────────────
49	
50	function loadDepartments() {
51	  const raw = readJson(DEPARTMENTS_PATH, { departments: {}, phases: {} });
52	  return raw;
53	}
54	
55	function saveDepartments(data) {
56	  data.updatedAt = new Date().toISOString();
57	  writeJson(DEPARTMENTS_PATH, data);
58	}
59	
60	function listDepartments() {
61	  const { departments } = loadDepartments();
62	  return Object.values(departments || {})
63	    .filter((d) => d.active !== false)
64	    .sort((a, b) => (a.order || 0) - (b.order || 0));
65	}
66	
67	function getDepartment(id) {
68	  const { departments } = loadDepartments();
69	  return departments?.[id] || null;
70	}
71	
72	function listPhases() {
73	  const { phases } = loadDepartments();
74	  return Object.values(phases || {}).sort((a, b) => (a.order || 0) - (b.order || 0));
75	}
76	
77	function getPhase(id) {
78	  const { phases } = loadDepartments();
79	  return phases?.[id] || null;
80	}
81	
82	// ──────────────────────────────────────────────────────────────────────────
83	//  Registry
84	// ──────────────────────────────────────────────────────────────────────────
85	
86	function loadRegistry() {
87	  return readJson(REGISTRY_PATH, { version: 1, agents: {} });
88	}
89	
90	function saveRegistry(data) {
91	  data.updatedAt = new Date().toISOString();
92	  writeJson(REGISTRY_PATH, data);
93	}
94	
95	function listAgentRecords() {
96	  const { agents } = loadRegistry();
97	  return Object.values(agents || {});
98	}
99	
100	function findAgent(id) {
101	  const { agents } = loadRegistry();
102	  return agents?.[id] || null;
103	}
104	
105	function upsertAgent(id, patch) {
106	  const registry = loadRegistry();
107	  registry.agents = registry.agents || {};
108	  const existing = registry.agents[id] || { id };
109	  registry.agents[id] = {
110	    ...existing,
111	    ...patch,
112	    id,
113	    updatedAt: new Date().toISOString(),
114	  };
115	  saveRegistry(registry);
116	  return registry.agents[id];
117	}
118	
119	function removeAgent(id) {
120	  const registry = loadRegistry();
121	  if (registry.agents?.[id]) {
122	    delete registry.agents[id];
123	    saveRegistry(registry);
124	    return true;
125	  }
126	  return false;
127	}
128	
129	function findAgentsByDepartment(departmentId) {
130	  return listAgentRecords().filter((a) => a.department === departmentId);
131	}
132	
133	function findAgentsByPhase(phaseId) {
134	  return listAgentRecords().filter((a) => a.phase === phaseId);
135	}
136	
137	function findDirectReports(managerId) {
138	  return listAgentRecords().filter((a) => a.reportsTo === managerId);
139	}
140	
141	// ──────────────────────────────────────────────────────────────────────────
142	//  Org chart composition — combines registry records with disk-parsed agents
143	// ──────────────────────────────────────────────────────────────────────────
144	
145	/**
146	 * Build a complete org-chart response combining:
147	 *   - Department metadata from departments.json
148	 *   - Per-agent records from registry.json
149	 *   - Live agent metadata (name, description, model, tools) from the
150	 *     caller-supplied `agentMap` keyed by filename
151	 *
152	 * `agentMap` is injected so this module stays decoupled from server.js's
153	 * agent parser. Typical caller:
154	 *
155	 *   const agentMap = Object.fromEntries(
156	 *     listAgents(path.join(CLAUDE_DIR, 'agents')).map((a) => [a.filename, a])
157	 *   );
158	 *   const chart = org.buildOrgChart(agentMap);
159	 */
160	function buildOrgChart(agentMap = {}) {
161	  const { departments, phases } = loadDepartments();
162	  const { agents: registry } = loadRegistry();
163	
164	  const nodes = [];
165	  const agentIds = Object.keys(registry || {});
166	
167	  for (const id of agentIds) {
168	    const record = registry[id];
169	    const disk = agentMap[id] || null;
170	
171	    // Skip if registry references an agent that has no .md file on disk
172	    // (we still keep it if status === 'probation' for new hires in flight)
173	    if (!disk && record.status !== 'probation' && record.status !== 'pending') {
174	      continue;
175	    }
176	
177	    const phaseInfo = record.phase ? phases?.[record.phase] : null;
178	    const deptInfo = departments?.[record.department] || null;
179	
180	    nodes.push({
181	      id,
182	      name: disk?.name || record.name || id,
183	      title: record.title || 'Agent',
184	      tier: record.tier || 'engineer',
185	      model: disk?.model || record.model || 'sonnet',
186	      tools: disk?.tools || '',
187	      description: disk?.description || record.description || '',
188	      department: record.department || null,
189	      departmentLabel: deptInfo?.label || null,
190	      departmentColor: deptInfo?.color || '#6b7280',
191	      phase: record.phase || null,
192	      phaseLabel: phaseInfo?.label || null,
193	      phaseColor: phaseInfo?.color || '#6b7280',
194	      reportsTo: record.reportsTo || null,
195	      status: record.status || 'active',
196	      level: record.level ?? null,
197	      levelTitle: record.levelTitle ?? null,
198	      yearsOfExperience: record.yearsOfExperience ?? null,
199	      experiencePoints: record.experiencePoints ?? null,
200	    });
201	  }
202	
203	  // Edges: reporting lines
204	  const nodeById = Object.fromEntries(nodes.map((n) => [n.id, n]));
205	  const edges = [];
206	  for (const node of nodes) {
207	    if (node.reportsTo && nodeById[node.reportsTo]) {
208	      edges.push({ from: node.reportsTo, to: node.id });
209	    }
210	  }
211	
212	  // Phases in pipeline view
213	  const phaseList = Object.values(phases || {})
214	    .sort((a, b) => (a.order || 0) - (b.order || 0))
215	    .map((p) => ({
216	      id: p.id,
217	      label: p.label,
218	      description: p.description,
219	      color: p.color,
220	      agents: nodes
221	        .filter((n) => n.phase === p.id)
222	        .map((n) => ({
223	          id: n.id,
224	          name: n.name,
225	          title: n.title,
226	          model: n.model,
227	          description: n.description,
228	          level: n.level,
229	          yearsOfExperience: n.yearsOfExperience,
230	        })),
231	    }));
232	
233	  // Departments in org view
234	  const departmentList = Object.values(departments || {})
235	    .filter((d) => d.active !== false)
236	    .sort((a, b) => (a.order || 0) - (b.order || 0))
237	    .map((d) => ({
238	      id: d.id,
239	      label: d.label,
240	      description: d.description,
241	      color: d.color,
242	      icon: d.icon,
243	      head: d.head,
244	      members: nodes.filter((n) => n.department === d.id),
245	    }));
246	
247	  // Stats
248	  const stats = {
249	    totalAgents: nodes.length,
250	    byModel: {},
251	    byTier: {},
252	    byPhase: {},
253	    byDepartment: {},
254	    byStatus: {},
255	    byLevel: {},
256	  };
257	  for (const n of nodes) {
258	    stats.byModel[n.model] = (stats.byModel[n.model] || 0) + 1;
259	    stats.byTier[n.tier] = (stats.byTier[n.tier] || 0) + 1;
260	    if (n.phase) stats.byPhase[n.phase] = (stats.byPhase[n.phase] || 0) + 1;
261	    if (n.department) stats.byDepartment[n.department] = (stats.byDepartment[n.department] || 0) + 1;
262	    stats.byStatus[n.status] = (stats.byStatus[n.status] || 0) + 1;
263	    if (n.level != null) stats.byLevel[n.level] = (stats.byLevel[n.level] || 0) + 1;
264	  }
265	
266	  return {
267	    nodes,
268	    edges,
269	    phases: phaseList,
270	    departments: departmentList,
271	    stats,
272	  };
273	}
274	
275	// ──────────────────────────────────────────────────────────────────────────
276	//  Self-heal: detect drift between registry and disk
277	// ──────────────────────────────────────────────────────────────────────────
278	
279	/**
280	 * Compare registry.json against the actual agent .md files on disk.
281	 * Returns { onlyOnDisk: [], onlyInRegistry: [] } — agents present in one
282	 * but not the other. HR uses this to auto-heal the registry.
283	 */
284	function detectDrift(agentMap) {
285	  const { agents: registry } = loadRegistry();
286	  const registryIds = new Set(Object.keys(registry || {}));
287	  const diskIds = new Set(Object.keys(agentMap));
288	
289	  const onlyOnDisk = [...diskIds].filter((id) => !registryIds.has(id));
290	  const onlyInRegistry = [...registryIds].filter(
291	    (id) => !diskIds.has(id) && registry[id].status !== 'probation'
292	  );
293	
294	  return { onlyOnDisk, onlyInRegistry };
295	}
296	
297	module.exports = {
298	  // paths (exposed for HR module)
299	  ORG_DIR,
300	  DEPARTMENTS_PATH,
301	  REGISTRY_PATH,
302	
303	  // departments
304	  loadDepartments,
305	  saveDepartments,
306	  listDepartments,
307	  getDepartment,
308	  listPhases,
309	  getPhase,
310	
311	  // registry
312	  loadRegistry,
313	  saveRegistry,
314	  listAgentRecords,
315	  findAgent,
316	  upsertAgent,
317	  removeAgent,
318	  findAgentsByDepartment,
319	  findAgentsByPhase,
320	  findDirectReports,
321	
322	  // compose
323	  buildOrgChart,
324	  detectDrift,
325	};
