1	/**
2	 * HR Module — People operations for the Polyglot agent factory.
3	 *
4	 * Exposes operations that Cadence, Roster, and Witness execute via their
5	 * agent .md prompts, and that the /hr UI calls directly.
6	 *
7	 * Depends on:
8	 *   - src/org.js       — registry + departments source of truth
9	 *   - src/experience.js — level/YoE/skills computation
10	 *
11	 * Owned data paths (all under ~/.claude/org/):
12	 *   - reviews/YYYY-WW.json         — weekly Cadence review files
13	 *   - reviews/latest.md            — human-readable latest summary for Rex
14	 *   - witness-log.jsonl            — append-only accountability log
15	 *   - daily-scores.jsonl           — per-agent daily accountability scores
16	 *   - recommendations.json         — current Witness PIP/promotion candidates
17	 *   - training-queue.json          — pending curriculum per agent
18	 *   - capability-gaps.jsonl        — append-only log of detected gaps
19	 *   - antipattern-signatures.json  — detection rules
20	 *   - onboarding/<agent>.json      — probationary checklists for new hires
21	 *   - playbooks/onboarding.md      — standard onboarding steps
22	 *   - playbooks/pip.md             — PIP protocol
23	 */
24	
25	const fs = require('fs');
26	const path = require('path');
27	const os = require('os');
28	
29	const HOME = os.homedir();
30	const ORG_DIR = path.join(HOME, '.claude', 'org');
31	const REVIEWS_DIR = path.join(ORG_DIR, 'reviews');
32	const ONBOARDING_DIR = path.join(ORG_DIR, 'onboarding');
33	const PLAYBOOKS_DIR = path.join(ORG_DIR, 'playbooks');
34	
35	const WITNESS_LOG = path.join(ORG_DIR, 'witness-log.jsonl');
36	const DAILY_SCORES = path.join(ORG_DIR, 'daily-scores.jsonl');
37	const RECOMMENDATIONS = path.join(ORG_DIR, 'recommendations.json');
38	const TRAINING_QUEUE = path.join(ORG_DIR, 'training-queue.json');
39	const CAPABILITY_GAPS = path.join(ORG_DIR, 'capability-gaps.jsonl');
40	const ANTIPATTERN_SIGS = path.join(ORG_DIR, 'antipattern-signatures.json');
41	const SKILL_INDEX = path.join(ORG_DIR, 'skill-index.json');
42	
43	// ──────────────────────────────────────────────────────────────────────────
44	//  File helpers
45	// ──────────────────────────────────────────────────────────────────────────
46	
47	function ensureDir(dir) {
48	  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
49	}
50	
51	function readJson(filePath, fallback) {
52	  try {
53	    if (!fs.existsSync(filePath)) return fallback;
54	    return JSON.parse(fs.readFileSync(filePath, 'utf-8'));
55	  } catch {
56	    return fallback;
57	  }
58	}
59	
60	function writeJson(filePath, data) {
61	  ensureDir(path.dirname(filePath));
62	  const tmp = filePath + '.tmp';
63	  fs.writeFileSync(tmp, JSON.stringify(data, null, 2));
64	  fs.renameSync(tmp, filePath);
65	}
66	
67	function appendJsonl(filePath, obj) {
68	  ensureDir(path.dirname(filePath));
69	  fs.appendFileSync(filePath, JSON.stringify(obj) + '\n');
70	}
71	
72	function readJsonl(filePath) {
73	  try {
74	    if (!fs.existsSync(filePath)) return [];
75	    return fs
76	      .readFileSync(filePath, 'utf-8')
77	      .split('\n')
78	      .filter(Boolean)
79	      .map((l) => { try { return JSON.parse(l); } catch { return null; } })
80	      .filter(Boolean);
81	  } catch {
82	    return [];
83	  }
84	}
85	
86	function currentIsoWeek(date = new Date()) {
87	  const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
88	  const dayNum = d.getUTCDay() || 7;
89	  d.setUTCDate(d.getUTCDate() + 4 - dayNum);
90	  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
91	  const week = Math.ceil(((d - yearStart) / 86400000 + 1) / 7);
92	  return `${d.getUTCFullYear()}-W${String(week).padStart(2, '0')}`;
93	}
94	
95	// ──────────────────────────────────────────────────────────────────────────
96	//  Registry views
97	// ──────────────────────────────────────────────────────────────────────────
98	
99	function getRegistry(orgModule) {
100	  const reg = orgModule.loadRegistry();
101	  const agents = Object.values(reg.agents || {});
102	  // Sort: by department, then by level desc, then by name
103	  agents.sort((a, b) => {
104	    if (a.department !== b.department) return (a.department || '').localeCompare(b.department || '');
105	    if ((b.level || 0) !== (a.level || 0)) return (b.level || 0) - (a.level || 0);
106	    return a.id.localeCompare(b.id);
107	  });
108	  return {
109	    version: reg.version || 1,
110	    updatedAt: reg.updatedAt,
111	    total: agents.length,
112	    agents,
113	  };
114	}
115	
116	function getAgentProfile(orgModule, agentId) {
117	  const record = orgModule.findAgent(agentId);
118	  if (!record) return null;
119	  // Enrich with direct reports + manager
120	  const reports = orgModule.findDirectReports(agentId);
121	  return {
122	    ...record,
123	    directReports: reports.map((r) => ({ id: r.id, title: r.title, level: r.level })),
124	  };
125	}
126	
127	// ──────────────────────────────────────────────────────────────────────────
128	//  Witness operations — accountability log
129	// ──────────────────────────────────────────────────────────────────────────
130	
131	function logWitnessEvent({ agent, runId, classification, meta = {} }) {
132	  const entry = {
133	    t: new Date().toISOString(),
134	    agent,
135	    runId: runId || null,
136	    class: classification,
137	    ...meta,
138	  };
139	  appendJsonl(WITNESS_LOG, entry);
140	  return entry;
141	}
142	
143	function getWitnessLog({ agent, days = 30, limit = 500 } = {}) {
144	  const all = readJsonl(WITNESS_LOG);
145	  const cutoff = Date.now() - days * 24 * 60 * 60 * 1000;
146	  let filtered = all.filter((e) => new Date(e.t).getTime() >= cutoff);
147	  if (agent) filtered = filtered.filter((e) => e.agent === agent);
148	  return filtered.slice(-limit);
149	}
150	
151	/**
152	 * Run the daily Witness sweep — classify recent runs, detect antipatterns,
153	 * compute daily scores, generate PIP/promotion recommendations.
154	 *
155	 * @param {object} orgModule    — src/org.js
156	 * @param {object} experienceModule — src/experience.js
157	 * @param {array}  agentRuns    — last 24h of agent-runs.json entries
158	 */
159	function runWitnessSweep(orgModule, experienceModule, agentRuns) {
160	  const startedAt = new Date().toISOString();
161	  const registry = orgModule.loadRegistry();
162	  const agents = registry.agents || {};
163	
164	  // 1. Classify each run in the window
165	  const cutoff = Date.now() - 24 * 60 * 60 * 1000;
166	  const recent = agentRuns.filter((r) => new Date(r.timestamp).getTime() >= cutoff);
167	  const classified = [];
168	
169	  for (const run of recent) {
170	    let classification = 'SUCCESS';
171	    if (run.status === 'failed' || run.status === 'error' || run.error) {
172	      classification = 'FAILURE';
173	    } else if (run.duration && run.duration > 600000) {
174	      classification = 'TIMEOUT';
175	    } else if (run.status === 'success') {
176	      classification = 'SUCCESS';
177	    } else {
178	      classification = 'UNCLASSIFIED';
179	    }
180	    const entry = logWitnessEvent({
181	      agent: run.agentName,
182	      runId: run.id,
183	      classification,
184	      meta: {
185	        durationMs: run.duration,
186	        taskType: run.taskType || 'general',
187	        project: run.metadata?.projectId || null,
188	      },
189	    });
190	    classified.push(entry);
191	  }
192	
193	  // 2. Compute daily scores
194	  const scoresByAgent = {};
195	  for (const entry of classified) {
196	    if (!scoresByAgent[entry.agent]) {
197	      scoresByAgent[entry.agent] = { agent: entry.agent, success: 0, failure: 0, antipattern: 0, regression: 0, score: 0 };
198	    }
199	    const s = scoresByAgent[entry.agent];
200	    if (entry.class === 'SUCCESS') s.success++;
201	    else if (entry.class === 'FAILURE' || entry.class === 'TIMEOUT') s.failure++;
202	    else if (entry.class === 'ANTIPATTERN') s.antipattern++;
203	    else if (entry.class === 'REGRESSION') s.regression++;
204	  }
205	  for (const s of Object.values(scoresByAgent)) {
206	    s.score = s.success * 1 - s.failure * 1 - s.antipattern * 2 - s.regression * 3;
207	    s.date = new Date().toISOString().slice(0, 10);
208	    appendJsonl(DAILY_SCORES, s);
209	  }
210	
211	  // 3. Generate PIP + promotion recommendations
212	  const pipCandidates = [];
213	  const promotionCandidates = [];
214	
215	  for (const id of Object.keys(agents)) {
216	    const a = agents[id];
217	    if (a.status === 'retired' || a.status === 'pip') continue;
218	
219	    const stats = a.stats || {};
220	    const successRate = stats.successRate ?? 1;
221	    const antipatterns = stats.antipatternsTriggered || 0;
222	
223	    // PIP triggers
224	    if (stats.totalRuns >= 20 && successRate < 0.7) {
225	      pipCandidates.push({
226	        agent: id,
227	        reasons: [`Success rate ${Math.round(successRate * 100)}%`],
228	        severity: successRate < 0.5 ? 'high' : 'medium',
229	      });
230	    } else if (antipatterns >= 3) {
231	      pipCandidates.push({
232	        agent: id,
233	        reasons: [`${antipatterns} antipatterns triggered`],
234	        severity: 'medium',
235	      });
236	    }
237	
238	    // Promotion eligibility — level crossed threshold, success rate high, 30+ days at level
239	    if (a.level != null && a.level < 8 && successRate >= 0.85 && antipatterns === 0) {
240	      const needsRuns = a.level >= 3 ? (stats.patternsContributed || 0) >= 1 : true;
241	      if (needsRuns) {
242	        promotionCandidates.push({
243	          agent: id,
244	          fromLevel: a.level,
245	          toLevel: a.level + 1,
246	          fromTitle: a.levelTitle,
247	          signals: [
248	            `${a.yearsOfExperience} YoE`,
249	            `${Math.round(successRate * 100)}% success`,
250	            `${stats.patternsContributed || 0} patterns`,
251	            `${antipatterns} antipatterns`,
252	          ],
253	        });
254	      }
255	    }
256	  }
257	
258	  const recommendations = {
259	    generatedAt: startedAt,
260	    completedAt: new Date().toISOString(),
261	    runsClassified: classified.length,
262	    pipCandidates,
263	    promotionCandidates,
264	  };
265	  writeJson(RECOMMENDATIONS, recommendations);
266	
267	  return recommendations;
268	}
269	
270	// ──────────────────────────────────────────────────────────────────────────
271	//  Cadence operations — promotion, PIP, hire, retire
272	// ──────────────────────────────────────────────────────────────────────────
273	
274	function promoteAgent(orgModule, experienceModule, agentId) {
275	  const record = orgModule.findAgent(agentId);
276	  if (!record) return { ok: false, error: 'Agent not found' };
277	  if (record.status === 'retired') return { ok: false, error: 'Cannot promote a retired agent' };
278	
279	  const currentLevel = record.level ?? 0;
280	  if (currentLevel >= 8) return { ok: false, error: 'Already at max level (Fellow)' };
281	
282	  const nextThreshold = experienceModule.LEVEL_THRESHOLDS[currentLevel + 1];
283	  if (!nextThreshold) return { ok: false, error: 'No higher level available' };
284	
285	  // Grant a promotion bonus: enough XP to cross the threshold
286	  const bonusYears = Math.max(0, nextThreshold.minYoE - (record.yearsOfExperience || 0)) + 0.1;
287	
288	  const updated = orgModule.upsertAgent(agentId, {
289	    level: currentLevel + 1,
290	    levelTitle: nextThreshold.title,
291	    levelColor: nextThreshold.color,
292	    canMentor: nextThreshold.canMentor,
293	    canShipProd: nextThreshold.canShipProd,
294	    yearsOfExperience: Math.round(((record.yearsOfExperience || 0) + bonusYears) * 10) / 10,
295	    lastPromoted: new Date().toISOString(),
