463	/**
464	 * Given a brief (natural language task description), find out if the
465	 * current roster can handle it. Uses simple keyword matching against
466	 * each agent's skill vector from registry.json.
467	 */
468	function detectCapabilityGap(orgModule, brief, requiredSkillsHint = []) {
469	  const registry = orgModule.loadRegistry();
470	  const agents = Object.values(registry.agents || {})
471	    .filter((a) => a.status === 'active' || a.status === 'probation');
472	
473	  // Infer required skills from brief text if not explicitly given
474	  const inferredSkills = new Set(requiredSkillsHint);
475	  const briefLower = (brief || '').toLowerCase();
476	  const SKILL_HINTS = {
477	    react: ['react', 'component', 'frontend', 'ui'],
478	    typescript: ['typescript', 'ts'],
479	    nextjs: ['next.js', 'app router'],
480	    supabase: ['supabase', 'postgres', 'rls'],
481	    shopify: ['shopify', 'storefront', 'polaris'],
482	    billing: ['stripe', 'billing', 'subscription', 'payment', 'dodo'],
483	    auth: ['auth', 'oauth', 'session', 'login', 'sign in'],
484	    testing: ['test', 'vitest', 'playwright'],
485	    design: ['design', 'figma', 'ui/ux'],
486	    seo: ['seo', 'sitemap', 'meta'],
487	    deployment: ['deploy', 'railway', 'docker'],
488	    ai: ['llm', 'gpt', 'claude', 'prompt'],
489	    marketing: ['landing', 'copy', 'funnel', 'email'],
490	    research: ['validate', 'icp', 'interview', 'market'],
491	    debugging: ['bug', 'fix', 'error', 'crash'],
492	    architecture: ['architecture', 'system design', 'scalab'],
493	  };
494	  for (const [skill, hints] of Object.entries(SKILL_HINTS)) {
495	    if (hints.some((h) => briefLower.includes(h))) inferredSkills.add(skill);
496	  }
497	
498	  const required = [...inferredSkills];
499	  if (required.length === 0) {
500	    return {
501	      canHandle: true,
502	      confidence: 0.5,
503	      bestMatches: [],
504	      gaps: [],
505	      recommendation: 'proceed',
506	      note: 'No specific skills inferred from brief',
507	      inferredSkills: [],
508	    };
509	  }
510	
511	  // Score each agent against required skills
512	  const scored = agents.map((a) => {
513	    const skills = a.skills || {};
514	    let totalScore = 0;
515	    const matched = [];
516	    const missing = [];
517	    for (const req of required) {
518	      const s = skills[req]?.score || 0;
519	      if (s > 0) matched.push({ skill: req, score: s });
520	      else missing.push(req);
521	      totalScore += s;
522	    }
523	    return {
524	      agent: a.id,
525	      title: a.title,
526	      level: a.level,
527	      score: Math.round((totalScore / required.length) * 100) / 100,
528	      matched,
529	      missing,
530	    };
531	  });
532	
533	  scored.sort((a, b) => b.score - a.score);
534	  const bestMatches = scored.slice(0, 3);
535	
536	  // Determine gap + recommendation
537	  const topScore = bestMatches[0]?.score || 0;
538	  const allMissing = required.filter((r) => !scored.some((s) => s.matched.find((m) => m.skill === r && m.score >= 0.4)));
539	  const canHandle = topScore >= 0.7 && allMissing.length === 0;
540	
541	  let recommendation;
542	  if (canHandle) recommendation = 'proceed';
543	  else if (topScore >= 0.4) recommendation = `train-${bestMatches[0].agent}`;
544	  else recommendation = 'hire';
545	
546	  // Log the gap
547	  appendJsonl(CAPABILITY_GAPS, {
548	    t: new Date().toISOString(),
549	    brief: brief.slice(0, 200),
550	    inferredSkills: required,
551	    gaps: allMissing,
552	    bestAgent: bestMatches[0]?.agent || null,
553	    topScore,
554	    canHandle,
555	    recommendation,
556	  });
557	
558	  return {
559	    canHandle,
560	    confidence: topScore,
561	    bestMatches,
562	    gaps: allMissing,
563	    recommendation,
564	    inferredSkills: required,
565	  };
566	}
