573	 * Run the weekly Cadence review and write the review file + latest summary.
574	 * Applies all decisions (promotions/PIPs/retirements).
575	 */
576	function runCadenceReview(orgModule, experienceModule, agentRuns) {
577	  const week = currentIsoWeek();
578	  const reviewedAt = new Date().toISOString();
579	
580	  // 1. Refresh experience so decisions use current data
581	  experienceModule.recomputeAllExperience(orgModule);
582	
583	  // 2. Run a Witness sweep first so recommendations are current
584	  runWitnessSweep(orgModule, experienceModule, agentRuns);
585	  const recommendations = readJson(RECOMMENDATIONS, { pipCandidates: [], promotionCandidates: [] });
586	
587	  // 3. Apply promotions
588	  const promotions = [];
589	  for (const cand of recommendations.promotionCandidates || []) {
590	    const result = promoteAgent(orgModule, experienceModule, cand.agent);
591	    if (result.ok) promotions.push({ agent: cand.agent, to: result.agent.levelTitle });
592	  }
593	
594	  // 4. Apply PIPs
595	  const pipsOpened = [];
596	  for (const cand of recommendations.pipCandidates || []) {
597	    const result = openPip(orgModule, cand.agent, cand.reasons.join('; '));
598	    if (result.ok) pipsOpened.push({ agent: cand.agent });
599	  }
600	
601	  // 5. Write review file
602	  const review = {
603	    week,
604	    reviewedAt,
605	    director: 'cadence',
606	    promotions,
607	    pipsOpened,
608	    pipsClosed: [],
609	    retirements: [],
610	    newHires: [],
611	    capabilityGaps: readJsonl(CAPABILITY_GAPS).slice(-10),
612	    recommendations,
613	  };
614	  writeJson(path.join(REVIEWS_DIR, `${week}.json`), review);
615	
616	  // 6. Write human-readable latest.md
617	  const latest = [
618	    `# Cadence Review — ${week}`,
619	    `_${reviewedAt}_`,
620	    '',
621	    `**Promotions:** ${promotions.length}`,
622	    ...promotions.map((p) => `- ${p.agent} → ${p.to}`),
623	    '',
624	    `**PIPs opened:** ${pipsOpened.length}`,
625	    ...pipsOpened.map((p) => `- ${p.agent}`),
626	    '',
627	    `**Recommendations pending:**`,
628	    `- Promotion candidates: ${(recommendations.promotionCandidates || []).length}`,
629	    `- PIP candidates: ${(recommendations.pipCandidates || []).length}`,
630	  ].join('\n');
631	  fs.writeFileSync(path.join(REVIEWS_DIR, 'latest.md'), latest);
632	
633	  return review;
634	}
