220	/**
221	 * Compute a full experience profile for one agent.
222	 *
223	 * @param {object} registryRecord — from ~/.claude/org/registry.json
224	 * @param {array}  allRuns        — from agent-runs.json (pass once for all agents)
225	 * @returns {object} Full experience profile to merge back into registry
226	 */
227	function computeExperience(registryRecord, allRuns) {
228	  const weights = loadWeights();
229	  const agentId = registryRecord.id;
230	  const hiredAt = registryRecord.hiredAt ? new Date(registryRecord.hiredAt) : new Date();
231	  const ageDays = Math.max(0, (Date.now() - hiredAt.getTime()) / (1000 * 60 * 60 * 24));
232	
233	  // 1. Training depth
234	  const fileStats = readAgentFileStats(agentId);
235	  const fileKb = fileStats.sizeBytes / 1024;
236	
237	  // 2. Run stats
238	  const runStats = computeRunStats(agentId, allRuns);
239	
240	  // 3. Pattern contributions
241	  const patternsContributed = countPatternsContributed(agentId);
242	
243	  // 4. Antipatterns triggered
244	  const antipatternsTriggered = countAntipatternsTriggered(agentId);
245	
246	  // 5. Compute YoE
247	  const yoeTraining = fileKb / weights.trainingKbPerYear;
248	  const yoeRuns = runStats.totalRuns / weights.runsPerYear;
249	  const yoeTenure = ageDays / weights.daysPerYear;
250	  const yoePatterns = patternsContributed * weights.patternWeight;
251	  const yoeSuccess = runStats.successRate * weights.successBonus;
252	  const yoeAntipatterns = -antipatternsTriggered * weights.antipatternPenalty;
253	
254	  const yearsOfExperience = Math.max(
255	    0,
256	    yoeTraining + yoeRuns + yoeTenure + yoePatterns + yoeSuccess + yoeAntipatterns
257	  );
258	
259	  // 6. Level from YoE
260	  const levelInfo = levelForYoE(yearsOfExperience);
261	
262	  // 7. Skills
263	  const skills = computeSkillVector(agentId);
264	  const weaknesses = identifyWeaknesses(skills);
265	
266	  // 8. Experience points (separate from YoE, used for UI progress bars)
267	  const experiencePoints = Math.round(yearsOfExperience * 100);
268	
269	  // 9. Next level threshold (for progress-to-next-level UI)
270	  const nextLevel = LEVEL_THRESHOLDS[levelInfo.level + 1] || null;
271	  const progressToNext = nextLevel
272	    ? Math.min(1, (yearsOfExperience - levelInfo.minYoE) / (nextLevel.minYoE - levelInfo.minYoE))
273	    : 1;
274	
275	  return {
276	    // Level
277	    level: levelInfo.level,
278	    levelTitle: levelInfo.title,
279	    levelColor: levelInfo.color,
280	    canMentor: levelInfo.canMentor,
281	    canShipProd: levelInfo.canShipProd,
282	    // Experience
283	    yearsOfExperience: Math.round(yearsOfExperience * 10) / 10,
284	    experiencePoints,
285	    progressToNext: Math.round(progressToNext * 100) / 100,
286	    nextLevelTitle: nextLevel?.title || null,
287	    // Breakdown (for HR UI transparency)
288	    breakdown: {
289	      training: Math.round(yoeTraining * 10) / 10,
290	      runs: Math.round(yoeRuns * 10) / 10,
291	      tenure: Math.round(yoeTenure * 10) / 10,
292	      patterns: Math.round(yoePatterns * 10) / 10,
293	      success: Math.round(yoeSuccess * 10) / 10,
294	      antipatterns: Math.round(yoeAntipatterns * 10) / 10,
295	    },
296	    // Underlying stats
297	    stats: {
298	      fileSizeKb: Math.round(fileKb * 10) / 10,
299	      fileWords: fileStats.words,
300	      totalRuns: runStats.totalRuns,
301	      successRuns: runStats.successRuns,
302	      failedRuns: runStats.failedRuns,
303	      successRate: Math.round(runStats.successRate * 100) / 100,
304	      avgDurationMs: Math.round(runStats.avgDurationMs),
305	      lastRunAt: runStats.lastRunAt,
306	      ageDays: Math.round(ageDays * 10) / 10,
307	      patternsContributed,
308	      antipatternsTriggered,
309	    },
310	    // Skills
311	    skills,
312	    weaknesses,
313	    // Metadata
314	    computedAt: new Date().toISOString(),
315	  };
316	}
