318	/**
319	 * Recompute experience for every agent in the registry and write the result
320	 * back to registry.json. Called nightly by Roster (Phase 5 cron) and on
321	 * demand via POST /api/hr/recompute-experience.
322	 *
323	 * @param {object} orgModule — the src/org.js module (injected to avoid circular dep)
324	 * @returns {object} Summary { updated, errors, durationMs }
325	 */
326	function recomputeAllExperience(orgModule) {
327	  const started = Date.now();
328	  const allRuns = loadAgentRuns();
329	  const registry = orgModule.loadRegistry();
330	  const agentIds = Object.keys(registry.agents || {});
331	
332	  let updated = 0;
333	  const errors = [];
334	
335	  for (const id of agentIds) {
336	    try {
337	      const record = registry.agents[id];
338	      const profile = computeExperience(record, allRuns);
339	      registry.agents[id] = { ...record, ...profile };
340	      updated++;
341	    } catch (err) {
342	      errors.push({ id, error: err.message });
343	    }
344	  }
345	
346	  orgModule.saveRegistry(registry);
347	
348	  return {
349	    updated,
350	    total: agentIds.length,
351	    errors,
352	    durationMs: Date.now() - started,
353	  };
354	}
