140	function acquireLock() {
141	  ensureDir(path.dirname(LOCK_PATH));
142	  if (fs.existsSync(LOCK_PATH)) {
143	    try {
144	      const stat = fs.statSync(LOCK_PATH);
145	      if (Date.now() - stat.mtimeMs < LOCK_STALE_MS) {
146	        return false; // active lock
