148	      // stale — reclaim
149	      log('warn', 'stale_lock_reclaimed', { ageMs: Date.now() - stat.mtimeMs });
150	    } catch {}
151	  }
152	  try {
153	    fs.writeFileSync(LOCK_PATH, String(process.pid), { flag: 'w' });
154	    return true;
155	  } catch {
156	    return false;
157	  }
158	}
