288	async function verifyRemote() {
289	  const cfg = getBackupConfig();
290	  if (!cfg || !cfg.repoUrl) {
291	    return { ok: false, code: 'NOT_CONFIGURED', detail: 'No backup configured' };
292	  }
293	  const token = decryptToken(cfg.tokenEnc || '');
294	  if (!token) {
295	    return { ok: false, code: 'NO_TOKEN', detail: 'Token missing or undecryptable' };
296	  }
297	  const parsed = parseRepoUrl(cfg.repoUrl);
298	  if (!parsed) {
299	    return { ok: false, code: 'BAD_URL', detail: 'Repo URL must be https://github.com/OWNER/NAME(.git)' };
300	  }
301	
302	  // 1. Token identity — /user
303	  const whoami = await githubRequest({ method: 'GET', pathname: '/user', token });
304	  if (whoami.status === 401) {
305	    return { ok: false, code: 'AUTH_INVALID', detail: 'Token rejected by GitHub', repo: parsed };
306	  }
307	  if (whoami.status !== 200) {
308	    return { ok: false, code: 'NETWORK', detail: whoami.error || `GitHub API ${whoami.status}`, repo: parsed };
309	  }
310	  const user = whoami.body?.login;
311	
312	  // 2. Token scopes — classic PATs expose them via header; fine-grained return null
313	  const scopes = (whoami.headers?.['x-oauth-scopes'] || '').split(',').map((s) => s.trim()).filter(Boolean);
314	
315	  // 3. Repo existence — /repos/:owner/:name
316	  const repo = await githubRequest({
317	    method: 'GET',
318	    pathname: `/repos/${parsed.owner}/${parsed.name}`,
319	    token,
320	  });
321	
322	  if (repo.status === 404) {
323	    return {
324	      ok: false,
325	      code: 'REPO_NOT_FOUND',
326	      detail: `Repository ${parsed.owner}/${parsed.name} does not exist (or token can't see it)`,
327	      repo: parsed,
328	      user,
329	      scopes,
330	      canCreate: parsed.owner === user || scopes.includes('repo'),
331	    };
332	  }
333	  if (repo.status === 403) {
334	    return { ok: false, code: 'PERMISSION_DENIED', detail: 'Token lacks access to this repo', repo: parsed, user, scopes };
335	  }
336	  if (repo.status !== 200) {
337	    return { ok: false, code: 'NETWORK', detail: repo.error || `GitHub API ${repo.status}`, repo: parsed };
338	  }
339	
340	  // 4. Write permission
341	  const canWrite = !!repo.body?.permissions?.push;
342	  if (!canWrite) {
343	    return {
344	      ok: false,
345	      code: 'PERMISSION_DENIED',
346	      detail: 'Token has read access but not write access',
347	      repo: parsed,
348	      user,
349	      scopes,
350	    };
351	  }
352	
353	  return {
354	    ok: true,
355	    code: 'OK',
356	    detail: 'Token valid, repo exists, write access confirmed',
357	    repo: parsed,
358	    user,
359	    scopes,
360	    isPrivate: !!repo.body?.private,
361	    defaultBranch: repo.body?.default_branch || 'main',
362	  };
363	}
