367	  if (!cfg || !cfg.repoUrl) return { ok: false, error: 'No backup configured' };
368	  const token = decryptToken(cfg.tokenEnc || '');
369	  if (!token) return { ok: false, error: 'Token missing' };
370	  const parsed = parseRepoUrl(cfg.repoUrl);
371	  if (!parsed) return { ok: false, error: 'Invalid repo URL' };
372	
373	  // Determine owner type — user vs org
374	  const whoami = await githubRequest({ method: 'GET', pathname: '/user', token });
375	  if (whoami.status !== 200) {
376	    return { ok: false, error: `Cannot verify token identity: ${whoami.status}` };
377	  }
378	  const user = whoami.body?.login;
