510	// Mirror src → dest, removing files in dest that no longer exist in src
511	function copyDirMirror(src, dest) {
512	  ensureDir(dest);
513	
514	  const srcEntries = new Set(fs.readdirSync(src));
515	  // Remove stale files in dest
516	  if (fs.existsSync(dest)) {
517	    for (const entry of fs.readdirSync(dest)) {
518	      if (!srcEntries.has(entry)) {
519	        fs.rmSync(path.join(dest, entry), { recursive: true, force: true });
520	      }
521	    }
522	  }
523	
524	  for (const entry of srcEntries) {
525	    if (entry === '.git') continue; // never copy git dirs
526	    const s = path.join(src, entry);
527	    const d = path.join(dest, entry);
528	    const st = fs.statSync(s);
529	    if (st.isFile()) {
530	      fs.copyFileSync(s, d);
531	    } else if (st.isDirectory()) {
532	      copyDirMirror(s, d);
533	    }
534	  }
535	}
