537	// Generate a descriptive commit message from the git status
538	async function generateCommitMessage(git) {
539	  const status = await git.status();
540	  const added = status.not_added.length + status.created.length;
541	  const modified = status.modified.length;
542	  const deleted = status.deleted.length;
543	
544	  if (added + modified + deleted === 0) {
545	    return null; // nothing to commit
546	  }
547	
548	  // Highlight up to 3 notable files
549	  const notable = [
550	    ...status.modified.slice(0, 2),
551	    ...status.not_added.slice(0, 2),
552	    ...status.created.slice(0, 2),
553	  ]
554	    .slice(0, 3)
555	    .map((f) => path.basename(f));
556	
557	  const parts = [];
558	  if (modified > 0) parts.push(`~${modified}`);
559	  if (added > 0) parts.push(`+${added}`);
560	  if (deleted > 0) parts.push(`-${deleted}`);
561	
562	  const summary = parts.join(' ');
563	  const files = notable.length > 0 ? ` — ${notable.join(', ')}` : '';
564	  return `Auto-backup: ${summary}${files}`;
565	}
