614	  } else {
615	    await git.addRemote('origin', authUrl);
616	  }
617	
618	  // Ensure we're on 'main' branch
619	  try {
620	    await git.checkoutLocalBranch('main');
621	  } catch {
622	    // Branch already exists, just check it out
623	    try {
624	      await git.checkout('main');
