644	async function doBackup({ skipPush = false } = {}) {
645	  const cfg = getBackupConfig();
646	  if (!cfg || !cfg.enabled) {
647	    return { ok: false, error: 'Backup not configured or disabled' };
648	  }
649	  if (!cfg.repoUrl) {
650	    return { ok: false, error: 'No repo URL configured' };
651	  }
652	
653	  if (!acquireLock()) {
654	    return { ok: false, error: 'Another backup is already running' };
655	  }
656	
657	  const startedAt = Date.now();
658	  const state = loadState();
659	  const queue = loadQueue();
660	  const token = decryptToken(cfg.tokenEnc || '');
661	
662	  try {
663	    log('info', 'backup_start', { skipPush });
664	
665	    syncToRepo();
666	    const git = await initRepo(cfg.repoUrl, token);
667	
668	    await git.add('./*');
669	    await git.add('.gitignore');
670	
671	    const message = await generateCommitMessage(git);
672	    if (!message) {
673	      if (!skipPush && queue.pending > 0) {
674	        await pushQueued(git, cfg);
675	      }
676	      state.lastBackupAt = new Date().toISOString();
677	      state.lastBackupStatus = 'noop';
678	      state.lastBackupError = null;
679	      state.lastBackupDiagnosis = null;
680	      saveState(state);
681	      log('info', 'backup_noop', { durationMs: Date.now() - startedAt });
682	      return { ok: true, committed: false, pushed: queue.pending === 0 };
683	    }
684	
685	    await git.commit(message);
686	    state.commitCount = (state.commitCount || 0) + 1;
687	    const gitLog = await git.log(['-1']).catch(() => null);
688	    if (gitLog?.latest?.hash) state.lastCommitSha = gitLog.latest.hash;
689	
690	    let pushed = false;
691	    let diagnosis = null;
692	    if (!skipPush) {
693	      try {
694	        await git.push(['-u', 'origin', 'main']);
695	        pushed = true;
696	        queue.pending = 0;
697	        queue.lastFailedPush = null;
698	      } catch (pushErr) {
699	        diagnosis = classifyGitError(pushErr.message);
700	        queue.pending = (queue.pending || 0) + 1;
701	        queue.lastFailedPush = {
702	          at: new Date().toISOString(),
703	          error: pushErr.message,
704	          diagnosis,
705	        };
706	        log('warn', 'push_failed', { code: diagnosis.code });
707	      }
708	      saveQueue(queue);
709	    }
710	
711	    state.lastBackupAt = new Date().toISOString();
712	    state.lastBackupStatus = pushed ? 'pushed' : (skipPush ? 'committed' : 'queued');
713	    state.lastBackupError = diagnosis ? diagnosis.detail : null;
714	    state.lastBackupDiagnosis = diagnosis;
715	    saveState(state);
716	
717	    log('info', 'backup_done', {
718	      pushed,
719	      committed: true,
720	      durationMs: Date.now() - startedAt,
721	      code: diagnosis?.code || 'OK',
722	    });
723	
724	    return { ok: true, committed: true, pushed, message, diagnosis };
725	  } catch (err) {
726	    const diagnosis = classifyGitError(err.message);
727	    state.lastBackupAt = new Date().toISOString();
728	    state.lastBackupStatus = 'error';
729	    state.lastBackupError = diagnosis.detail;
730	    state.lastBackupDiagnosis = diagnosis;
731	    saveState(state);
732	    log('error', 'backup_error', { code: diagnosis.code, raw: err.message });
733	    return { ok: false, error: err.message, diagnosis };
734	  } finally {
735	    releaseLock();
736	  }
737	}
