771	// Exponential backoff for queued push retry: 1m → 2m → 5m → 15m → 30m (capped)
772	const RETRY_SCHEDULE_MS = [60_000, 120_000, 300_000, 900_000, 1_800_000];
773	
774	function scheduleRetryPush() {
775	  if (retryTimer) clearTimeout(retryTimer);
776	  const queue = loadQueue();
777	  if (!queue.pending || queue.pending === 0) return;
778	  const attempt = Math.min(queue.pending - 1, RETRY_SCHEDULE_MS.length - 1);
779	  const delay = RETRY_SCHEDULE_MS[attempt];
780	  retryTimer = setTimeout(async () => {
781	    if (backupInProgress) { scheduleRetryPush(); return; }
782	    backupInProgress = true;
783	    try {
784	      const result = await retryPush();
785	      if (!result.ok) scheduleRetryPush();
786	    } finally {
787	      backupInProgress = false;
788	    }
789	  }, delay);
790	}
