269	    const { data, content: body } = matter(content);
270	    const stats = fs.statSync(filePath);
271	    return {
272	      filename: path.basename(filePath, '.md'),
273	      path: filePath,
274	      frontmatter: data,
275	      name: data.name || path.basename(filePath, '.md'),
276	      description: data.description || '',
277	      model: data.model || '',
278	      tools: data.tools || '',
279	      body: body.trim(),
280	      raw: content,
281	      updatedAt: stats.mtime.toISOString(),
282	    };
283	  } catch (e) {
284	    return null;
285	  }
