435	function discoverProjects(dirs) {
436	  const projects = [];
437	  for (const dir of dirs) {
438	    const resolved = dir.replace(/^~/, HOME);
439	    if (!fs.existsSync(resolved)) continue;
440	    try {
441	      const entries = fs.readdirSync(resolved, { withFileTypes: true });
442	      for (const entry of entries) {
443	        if (!entry.isDirectory()) continue;
444	        if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
445	        const projectPath = path.join(resolved, entry.name);
446	        const hasClaudeDir = fs.existsSync(path.join(projectPath, '.claude'));
447	        const hasClaudeMd = fs.existsSync(path.join(projectPath, 'CLAUDE.md'));
448	        const hasPackageJson = fs.existsSync(path.join(projectPath, 'package.json'));
449	        const hasPubspec = fs.existsSync(path.join(projectPath, 'pubspec.yaml'));
450	        if (hasClaudeDir || hasClaudeMd || hasPackageJson || hasPubspec) {
451	          const agents = listAgents(path.join(projectPath, '.claude', 'agents'));
452	          const commands = listMdFiles(path.join(projectPath, '.claude', 'commands'));
453	          const rules = listMdFiles(path.join(projectPath, '.claude', 'rules'));
454	          projects.push({
455	            id: Buffer.from(projectPath).toString('base64url'),
456	            name: entry.name,
457	            path: projectPath,
458	            displayPath: projectPath.replace(HOME, '~'),
459	            hasClaudeDir,
460	            hasClaudeMd,
461	            agentCount: agents.length,
462	            commandCount: commands.length,
463	            ruleCount: rules.length,
464	            agents,
465	            commands: commands.map(c => c.name),
466	            rules: rules.map(r => r.name),
467	          });
468	        }
469	      }
470	    } catch {}
471	  }
472	  return projects;
473	}
